function useInView(threshold = 0.15) {
  const ref = useRef(null);
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setVisible(true); obs.disconnect(); } }, { threshold });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, []);
  return [ref, visible];
}

function Section({ id, children, style = {} }) {
  return <section id={id} style={{ position:"relative", ...style }}>{children}</section>;
}

function AnimBlock({ delay = 0, children, style = {} }) {
  const [ref, vis] = useInView();
  return (
    <div ref={ref} style={{ opacity: vis ? undefined : 0, animation: vis ? `fade-rise 0.9s ${delay}s ease-out both` : "none", ...style }}>
      {children}
    </div>
  );
}

// ── Accordion ────────────────────────────────────────────────────────────────
function Accordion({ items }) {
  const [open, setOpen] = useState(null);
  return (
    <div>
      {items.map((item, i) => (
        <div key={i} className="accordion-item">
          <button className={`accordion-btn ${open === i ? "open" : ""}`} onClick={() => setOpen(open === i ? null : i)}>
            <span>{item.q}</span>
            <span className="icon">+</span>
          </button>
          <div className={`accordion-content ${open === i ? "open" : ""}`}>
            <div className="accordion-inner">{item.a}</div>
          </div>
        </div>
      ))}
    </div>
  );
}

