  // ── Video fade-loop ───────────────────────────────────────────────────────
  useEffect(() => {
    const vid = videoRef.current;
    if (!vid) return;
    const FADE = 0.5;
    vid.volume = 0;
    const tick = () => {
      if (!vid.paused && vid.duration) {
        const t = vid.currentTime, d = vid.duration;
        if (t < FADE) vid.style.opacity = t / FADE;
        else if (t > d - FADE) vid.style.opacity = (d - t) / FADE;
        else vid.style.opacity = 1;
      }
      rafRef.current = requestAnimationFrame(tick);
    };
    const onEnded = () => { vid.style.opacity = 0; setTimeout(() => { vid.currentTime = 0; vid.play(); }, 100); };
    vid.addEventListener("ended", onEnded);
    rafRef.current = requestAnimationFrame(tick);
    return () => { vid.removeEventListener("ended", onEnded); cancelAnimationFrame(rafRef.current); };
  }, []);

